mapper.insert:
insert into weaning_record_allocations (
    weaning_record_id, cage_id, alloc_count, male_count, female_count
)
values

    (
        #{r.weaningRecordId}, #{r.cageId}, #{r.allocCount},
        #{r.maleCount}, #{r.femaleCount}
    )

on duplicate key update
    alloc_count = alloc_count + values(alloc_count),
    male_count = case
        when male_count is null or values(male_count) is null then null
        else male_count + values(male_count)
    end,
    female_count = case
        when female_count is null or values(female_count) is null then null
        else female_count + values(female_count)
    end
